//! Runtime of the Rust SDKs generated by Archon: request building, parameter serialization, the middleware chain,
//! the transport (with manual redirects), authentication and the standard middleware.
//!
//! Generated SDKs carry a copy of this crate in `src/core/`; every item is re-exported from the module root.
#![forbid(unsafe_code)]

mod auth;
mod base64;
mod body;
mod client;
mod decode;
mod encoding;
mod errors;
mod file;
mod headers;
mod json_number;
mod middleware;
mod oauth2;
mod options;
mod params;
mod request;
mod response;
mod specs;
mod standard;
mod transport;
mod url;
mod values;

pub use crate::auth::{
    AuthConfig, AuthValue, BasicCredentials, BasicValue, CustomAuth, OAuth2ClientAuth, OAuth2ClientCredentials,
    OAuth2RefreshToken, OAuth2Value, TokenSet, TokenValue,
};
pub use crate::body::{ApiBody, FormBody, MultipartBody};
pub use crate::client::ApiClientCore;
pub use crate::decode::{decode_binary, decode_empty, decode_error_json, decode_error_text, decode_json, decode_text, ErrorBody};
pub use crate::errors::{ApiError, AuthError, DecodeError, Error, InvalidRequestError, TransportError};
pub use crate::file::ApiFile;
pub use crate::headers::ApiHeaders;
pub use crate::middleware::{middleware_fn, BoxFuture, CallContext, Middleware, Next};
pub use crate::oauth2::OAuth2TokenManager;
pub use crate::options::{http_client_builder, ClientOptions, RequestOptions};
#[doc(hidden)]
pub use crate::params::{serialize_cookie, serialize_header, serialize_path, serialize_query};
pub use crate::request::ApiRequest;
pub use crate::response::ApiResponse;
pub use crate::specs::{
    ApiKeyLocation, BodyKind, OperationSpec, ParamLocation, ParamSpec, ParamStyle, ResponseKind, SecurityRequirement,
    SecurityScheme, SecuritySchemeSpec,
};
pub use crate::standard::{LoggingMiddleware, Retry401Middleware, RetryMiddleware, UserAgentMiddleware};
pub use crate::values::RequestValues;
/// The HTTP method type (re-exported from reqwest).
pub use reqwest::Method;
